-- 0128 — قالب‌های مسیر سیستمی «طرح درمان» برای شکایات رایج کودک/نوجوان (خواست کارفرما)
-- محتوای هر قالب «اکیداً» از دارایی‌های authored موجود ساخته شده است:
--   · کلید هدف: فقط کلیدهای src/domain/clinical-engine/targets.ts (۲۲ هدف)
--   · کلید پراپ: فقط ce-probe-read-v1 / ce-probe-write-v1 / ce-probe-calc-v1 (پراپ‌های واقعی 0076/موتور)
--   · ابزار ارجاعی: فقط کلیدهای باتری موجود (battery-*.json — SNAP-IV، SCARED، ملاکی زبان، فرم‌های SLD)
--   · کارت‌های پیوسته: فقط رکوردهای بانک تمرین (seed 0043 + کارت‌های 0129) — بدون پیوند هوایی
--   · بدون ابزار بداعی، بدون هنجار عددی جدید، بدون متن دارای مالکیت — توصیف‌ها چارچوب‌محور و بدون بیش‌ادعا
-- «حساسیت حسی/تنظیم حسی» از این دسته حذف شد: هدف، پراپ و برگ مهارتی حسی در دارایی‌های موجود وجود ندارد
--   و ساختن قالب با کلید ساختگی نقض قانون «اکیداً از کلیدهای موجود» است — در صورت افزودن هدف حسی به
--   موتور بالینی، قالب آن در مایگریشن آینده اضافه می‌شود (additive؛ همین الگو).
-- الگوی D7: فقط-افزودنی، بدون CHECK، بدون trigger، idempotent با INSERT OR IGNORE و id/key ثابت لفظی.
-- فیلدها مطابق سرویس: protocol از ['learning','slow_learner','mental_ot','rehab']؛ steps JSON
--   ({key,title,hint?})؛ sessions_json JSON ({title,plan,criterion,items:[{type,text,done:false,linkId}]})؛
--   نوع آیتم‌ها از PATHWAY_ITEM_TYPES ('exercise','homework','game','instruction','event','probe','family').

INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000001',
  'sys-adhd-preschool',
  'ADHD پیش‌دبستانی — ساختار دیداری و بازی مهار تکانه',
  'قالب سیستمی برای پیش‌دبستانی با الگوی کم‌توجهی/تکانشگری: مشاهدهٔ ساختارمند، SNAP-IV والد، سپس دستور یک‌مرحله‌ای، تابلوی پیش‌بینی و بازی هدفمند مهار تکانه. مبتنی بر تمرین‌های خانهٔ موتور بالینی؛ جایگزین ارزیابی تخصصی نیست و ملاک دو-محیطی لازم است.',
  'mental_ot',
  'adhd',
  '[{"key":"observe","title":"مشاهدهٔ ساختارمند بازی و روتین","hint":"دو هفته ثبت رفتار در خانه/مهدکودک؛ الگوی تکانه و توجه ثبت شود، نه برچسب."},{"key":"assess","title":"ارزیابی چندمرجعی (SNAP-IV والد)","hint":"فرم ce-snap-iv-p-v1 از والد؛ ملاک دو-محیطی بعداً با فرم معلم/مربی تکمیل می‌شود."},{"key":"structure","title":"ساختار دیداری و قاعدهٔ کوتاه","hint":"دستور یک‌مرحله‌ای، تابلوی پیش‌بینی روز و تایمر بصری در خانه."},{"key":"play","title":"بازی هدفمند مهار تکانه","hint":"بازی‌های قاعده‌دار سبز-قرمز و نوبت‌گیری؛ بازخورد فوری و پاداش قابل پیش‌بینی."},{"key":"monitor","title":"پایش و بازبینی خانواده‌محور","hint":"بازپرسانی SNAP-IV پس از ۴ تا ۶ هفته و هماهنگی با مربی مهد/مدرسه."}]',
  '[{"title":"جلسهٔ ۱ — شرح‌حال و مشاهدهٔ بازی","plan":"ساخت فهرست رفتار هدف از گزارش والد؛ انتخاب دو رفتار قابل شمارش به‌عنوان مبنای پایش.","criterion":"توافق خانواده بر دو رفتار هدف و ثبت خط پایهٔ آن‌ها.","items":[{"type":"event","text":"ثبت فرم SNAP-IV والد (ce-snap-iv-p-v1) به‌عنوان خط پایه و مرجع بازسنجی.","done":false,"linkId":null},{"type":"instruction","text":"آموزش دستورِ یک‌مرحله‌ای: یک دستور در هر بار با تماس چشمی و تأیید شنیدن؛ بعد مرحلهٔ بعد.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000111"}]},{"title":"جلسهٔ ۲ — ساختار دیداری خانه","plan":"نصب چک‌لیست تیک‌دار روزانه و تابلوی برنامهٔ دیداری؛ تمرین روتین ثابت صبح و عصر.","criterion":"اجرای روتین سه روز پیاپی بدون یادآوری لفظی.","items":[{"type":"exercise","text":"چک‌لیست تیک‌دار: کارهای روز روی برگهٔ دیداری؛ هر تیک بازخورد فوری.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000112"},{"type":"homework","text":"تابلوی برنامهٔ روز با تصویر در ارتفاع دید کودک؛ هر شب دو دقیقه مروزن با کودک.","done":false,"linkId":null}]},{"title":"جلسهٔ ۳ — بازی مهار تکانه","plan":"معرفی بازی‌های قاعده‌دار خانه برای تمرین بازداری پاسخ؛ پاداش فوری پس از هر توقف موفق.","criterion":"دو بازی سبز-قرمز در هفته با پایداری قاعده تا پایان.","items":[{"type":"game","text":"چراغ توجه: بازی سبز-قرمز خانه برای تمرین توقف و شروع.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000207"},{"type":"exercise","text":"کارِ کوتاه با تایمر بصری: بازه‌های ۵ تا ۱۰ دقیقه‌ای با وقفهٔ حرکتی کوتاه بین بازه‌ها.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000110"}]},{"title":"جلسهٔ ۴ — گسترش توجه شنیداری","plan":"افزایش بار دستور از یک مرحله به دو مرحلهٔ بازی‌وار؛ حفظ موفقیت با پله‌های کوچک.","criterion":"اجرای دستور دومرحله‌ای در بازی بدون راهنمای تکراری.","items":[{"type":"game","text":"دستور دومرحله‌ایِ بازی‌وار: فهم شنیداری و حافظهٔ کاری در قالب بازی.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000211"},{"type":"family","text":"بازی نوبت‌گیری هفتگی با خواهر/برادر؛ قاعدهٔ دیداری و سقف زمان کوتاه.","done":false,"linkId":null}]},{"title":"جلسهٔ ۵ — جمع‌بندی و بازسنجی","plan":"مقایسهٔ رفتار هدف با خط پایه؛ تثبیت برنامهٔ خانه برای دو ماه بعد.","criterion":"کاهش گزارش‌شدهٔ رفتار هدف یا تثبیت برنامهٔ پایش ماهانه.","items":[{"type":"event","text":"بازپرسانی SNAP-IV والد و مقایسهٔ نمره‌ها با خط پایه (ce-snap-iv-p-v1).","done":false,"linkId":null},{"type":"event","text":"در صورت شروع دبستان، فرم معلم ce-snap-iv-t-v1 برای ملاک دو-محیطی ارسال شود.","done":false,"linkId":null},{"type":"instruction","text":"تداوم جدول ستارهٔ فوری و تایمر انتقال در خانه؛ تعریف از تلاش، نه نتیجه.","done":false,"linkId":null}]}]',
  1,
  1,
  'seed-m128'
);

INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000002',
  'sys-adhd-primary',
  'ADHD دبستان — ساختار، بازخورد فوری و آغازگری',
  'قالب سیستمی دبستان: SNAP-IV والد و معلم برای ملاک دو-محیطی، بازه‌های کوتاه تایمردار، چک‌لیست تیک‌دار و راهبرد آغازگری کار، همراه با هماهنگی معلم. مبتنی بر تمرین‌های خانهٔ موتور بالینی؛ تشخیص نیست و نیاز به بومی‌سازی درمانگر دارد.',
  'mental_ot',
  'adhd',
  '[{"key":"observe","title":"شرح‌حال و ثبت الگوی توجه","hint":"کار نیمه‌کاره، خطاهای بی‌دقتی و بی‌قراری در خانه و کلاس ثبت شود."},{"key":"assess","title":"SNAP-IV دو مرجع","hint":"ce-snap-iv-p-v1 + ce-snap-iv-t-v1؛ ملاک دو-محیطی بدون هر دو فرم کامل نیست."},{"key":"structure","title":"روتین و چک‌لیست دیداری","hint":"ساعت و جای ثابت تکلیف؛ چک‌لیست تیک‌دار با بازخورد فوری."},{"key":"intervene","title":"کار کوتاه تایمردار و آغازگری","hint":"بازه‌های ۵ تا ۱۰ دقیقه‌ای؛ راهبرد پنج‌قدمی شروع کار برای تعویق‌کاری."},{"key":"monitor","title":"بازسنجی و هماهنگی معلم","hint":"بازپرسانی SNAP-IV پس از ۴ تا ۶ هفته؛ پشتیبانی کلاسی تکه‌تکه‌کردن برگه‌ها."}]',
  '[{"title":"جلسهٔ ۱ — خط پایه و دو مرجع","plan":"ثبت خط پایهٔ توجه با فرم والد؛ برنامهٔ چک‌لیست تیک‌دار از همین هفته.","criterion":"هر دو فرم SNAP-IV در پرونده ثبت شده باشد.","items":[{"type":"event","text":"ثبت SNAP-IV والد (ce-snap-iv-p-v1) به‌عنوان خط پایه.","done":false,"linkId":null},{"type":"homework","text":"شروع چک‌لیست تیک‌دار روزانه؛ هر تیک بازخورد فوری و مشخص.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000112"}]},{"title":"جلسهٔ ۲ — تکمیل ملاک دو-محیطی","plan":"دریافت فرم معلم و هم‌رأیی خانه/مدرسه؛ تنظیم نشستن و محیط تکلیف.","criterion":"فرم معلم ثبت یا پیگیری مستند آن.","items":[{"type":"event","text":"در صورت نبود فرم معلم، ce-snap-iv-t-v1 برای معلم ارسال شود.","done":false,"linkId":null},{"type":"exercise","text":"کارِ کوتاه با تایمر بصری: بازه‌های ۵ تا ۱۰ دقیقه‌ای با وقفهٔ حرکتی.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000110"}]},{"title":"جلسهٔ ۳ — راهبرد آغازگری","plan":"شکستن تعویق‌کاری با پنج قدم شروع کار؛ روتین عصرانهٔ ثابت.","criterion":"شروع تکلیف بدون چانه‌زنی در سه روز از پنج روز هفته.","items":[{"type":"instruction","text":"پنج قدم شروع کار: آغازگری و سازماندهی وسایل به‌صورت روتین دیداری.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000208"},{"type":"homework","text":"روتین عصرانهٔ ثابت: ساعت و جای ثابت؛ برنامهٔ دیداری عصرانه.","done":false,"linkId":null}]},{"title":"جلسهٔ ۴ — تمرین ساختار در جلسه","plan":"اجرای بازهٔ تایمردار در جلسه و بازخورد فوری؛ تنظیم طول بازه با دادهٔ دو هفته.","criterion":"اتمام دو بازهٔ کاری پیاپی در جلسه.","items":[{"type":"exercise","text":"دستورِ یک‌مرحله‌ای: یک دستور در هر بار با تأیید شنیدن؛ الگو برای والد.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000111"},{"type":"homework","text":"پومودوروی کودک: ۱۰ دقیقه کار + ۵ دقیقه بازی با تایمر بصری.","done":false,"linkId":null}]},{"title":"جلسهٔ ۵ — هماهنگی معلم","plan":"پشتیبانی کلاسی: نشستن جلو، تکه‌تکه‌کردن برگه، مرور دستورها به‌صورت دیداری.","criterion":"توافق کتبی کوتاه با معلم روی دو سازگاری کلاسی.","items":[{"type":"family","text":"گفت‌وگوی معلم: تکه‌تکه‌کردن برگه‌ها و یادآوری دیداری؛ حذف بازی برای جبران ممنوع.","done":false,"linkId":null}]},{"title":"جلسهٔ ۶ — جمع‌بندی و بازسنجی","plan":"مقایسهٔ SNAP-IV با خط پایه؛ تصمیم تداوم/تعدیل برنامهٔ خانه و مدرسه.","criterion":"بازپرسانی انجام و نتیجه در پرونده ثبت شود.","items":[{"type":"event","text":"بازپرسانی SNAP-IV پس از ۴ تا ۶ هفته و مقایسهٔ نمره‌ها (ce-snap-iv-p-v1 / ce-snap-iv-t-v1).","done":false,"linkId":null},{"type":"instruction","text":"تداوم چک‌لیست و تعریف از تلاش و روش، نه فقط نتیجه.","done":false,"linkId":null}]}]',
  1,
  1,
  'seed-m128'
);

INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000003',
  'sys-sld-reading',
  'اختلال یادگیری خواندن — مسیر پنج‌مرحله‌ای با پروب روانی‌خواندن',
  'قالب سیستمی نارساخوانی: پروب روانی‌خواندن به‌عنوان خط پایه و پایش دوهفتگی با معیار تسلط ۸۰٪ در دو جلسهٔ پیاپی؛ مداخلهٔ آگاهی واجی، روانی‌خوانی با تکرار و واژه‌های پرتکرار از تمرین‌های موتور بالینی. بدون هنجار جدید و نیازمند تفسیر درمانگر.',
  'learning',
  'dyslexia',
  '[{"key":"baseline","title":"پروب پایهٔ خواندن","hint":"ce-probe-read-v1 — WCPM و دقت نسبت به انتظار پایه؛ نمرهٔ مبنا ثبت شود."},{"key":"phonology","title":"آگاهی واج‌شناختی","hint":"شکار صدا، تقطیع و حذف واج — پیش‌بینی‌کنندهٔ اصلی نارساخوانی."},{"key":"fluency","title":"روانی‌خوانی با تکرار","hint":"خواندن دوبارهٔ همان متن؛ روانی با تکرارِ همان خط ساخته می‌شود."},{"key":"words","title":"واژه‌های پرتکرار و هم‌خانواده","hint":"مخزن واژهٔ دیداری + کارت‌های هم‌خانوادهٔ واژه."},{"key":"monitor","title":"پروب پیگیری و جمع‌بندی","hint":"پروب هر دو جلسه؛ تسلط = ۸۰٪ معیار در دو جلسهٔ پیاپی (الگوی پایش 0076)."}]',
  '[{"title":"جلسهٔ ۱ — پروب پایه و شرح‌حال خواندن","plan":"اجرای پروب پایهٔ خواندن و مرور شواهد موجود؛ هدف SMART روی WCPM بسته می‌شود.","criterion":"ثبت WCPM و دقت مبنا در پروب مسیر.","items":[{"type":"probe","text":"اجرای ce-probe-read-v1 — ثبت WCPM و دقت به‌عنوان مبنا.","done":false,"linkId":null},{"type":"event","text":"مرور نتیجهٔ ce-sld-read-v1 و چک‌لیست معلم در صورت وجود؛ افتراق فقر فرصت.","done":false,"linkId":null}]},{"title":"جلسهٔ ۲ — آگاهی واجی","plan":"بازی واج‌ها: صدای اول/وسط/آخر و حذف واج؛ تمرین خانهٔ واج‌شماری.","criterion":"شکار صدای هدف در ۸ واژه از ۱۰.","items":[{"type":"exercise","text":"شکار صدا: صدای اول/وسط/آخر واژه — بازی با واج، پایهٔ پیوند صدا-حرف.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000102"},{"type":"homework","text":"آواشناسی خانه: تمرین روزانهٔ صدای اول/وسط/آخر با فهرست واژهٔ خودکار.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000201"}]},{"title":"جلسهٔ ۳ — روانی‌خوانی","plan":"خواندن دوبارهٔ یک‌خطی تا روان‌تر شدن؛ ثبت زمان برای دیدن پیشرفت.","criterion":"کاهش زمان خواندن همان خط در سه تکرار.","items":[{"type":"exercise","text":"خواندن دوبارهٔ یک‌خطی: همان خط سه بار تا روان‌تر شود.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000103"},{"type":"probe","text":"پروب پیگیری — WCPM نسبت به مبنا ثبت شود (ce-probe-read-v1).","done":false,"linkId":null}]},{"title":"جلسهٔ ۴ — واژه‌های پرتکرار","plan":"ساخت مخزن واژهٔ دیداری با کارت‌ها؛ ترکیب با هم‌خانوادهٔ واژه.","criterion":"خواندن تند و درست ۵ واژهٔ جدید در جلسه.","items":[{"type":"exercise","text":"کارت‌واژه‌های پرتکرار: تند و درست خواندن روزی چند واژه و جمع‌کردن موفقیت‌ها.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000101"},{"type":"homework","text":"کارت‌های هم‌خانوادهٔ واژه: ساختن خانوادهٔ واژه از یک ریشه.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000202"}]},{"title":"جلسهٔ ۵ — تثبیت و ترکیب","plan":"ترکیب آگاهی واجی + روانی‌خوانی در یک نشست؛ تمرین خانگی دوباره‌خوانی.","criterion":"پایداری سرعت در پروب جلسه.","items":[{"type":"probe","text":"پروب پیگیری دوم — مقایسه با جلسهٔ ۳ (ce-probe-read-v1).","done":false,"linkId":null},{"type":"homework","text":"خواندن دوبارهٔ یک‌خطی در خانه؛ هر خط سه بار.","done":false,"linkId":null}]},{"title":"جلسهٔ ۶ — جمع‌بندی دوره","plan":"پروب پایانی، مقایسهٔ روند با مبنا و تصمیم دورهٔ بعد؛ گزارش خانواده.","criterion":"معیار ۸۰٪ در دو جلسهٔ پیاپی یا تعریف دورهٔ تمدید.","items":[{"type":"probe","text":"پروب پایانی — مقایسه با مبنا و معیار تسلط ۸۰٪ در دو جلسهٔ پیاپی.","done":false,"linkId":null},{"type":"instruction","text":"گزارش پیشرفت به خانواده + برنامهٔ مرور واژه‌های پرتکرار تا جلسهٔ بعد.","done":false,"linkId":null}]}]',
  1,
  1,
  'seed-m128'
);

INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000004',
  'sys-sld-writing',
  'نارسانویسی — از الگوی حرکتی تا سطر تمیز',
  'قالب سیستمی نارسانویسی: پروب روانی‌نوشتن به‌عنوان مبنا، الگوی حرکتی پیش از کاغذ، سه سطرِ خوب (کیفیت نه حجم) و دیکتهٔ هدفمند؛ با معیار تسلط ۸۰٪ در دو جلسهٔ پیاپی. در صورت شک حرکت ظریف، مسیر کاردرمانی بازبینی شود.',
  'learning',
  'dysgraphia',
  '[{"key":"baseline","title":"پروب پایهٔ نوشتن","hint":"ce-probe-write-v1 — خطای دیکته و روانی نوشتن؛ نمونهٔ تاریخ‌دار ساخته شود."},{"key":"motor","title":"الگوی حرکتی نوشتن","hint":"نوشتن بزرگ در هوا و ماسه؛ الگوی حرکتی قبل از کاغذ تمرین می‌شود."},{"key":"quality","title":"سه سطرِ خوب","hint":"کیفیت، نه حجم: فقط سه سطر تمیز و روی خط."},{"key":"dictation","title":"دیکتهٔ هدفمند","hint":"اول بگو، بعد بنویس؛ بار ذهنی نوشتن سبک‌تر می‌شود."},{"key":"monitor","title":"پروب پیگیری و نمونهٔ تاریخ‌دار","hint":"پروب هر دو جلسه؛ تسلط = ۸۰٪ معیار در دو جلسهٔ پیاپی."}]',
  '[{"title":"جلسهٔ ۱ — پروب پایه و نمونهٔ تاریخ‌دار","plan":"اجرای پروب نوشتن و ساختن نمونهٔ تاریخ‌دار مبنای مقایسه.","criterion":"ثبت خطای دیکته و روانی مبنا.","items":[{"type":"probe","text":"اجرای ce-probe-write-v1 — ثبت خطای دیکتهٔ خطادار و روانی نوشتن.","done":false,"linkId":null},{"type":"event","text":"مرور نتیجهٔ ce-sld-wri-v1؛ در شک حرکت ظریف، ارزیابی کاردرمانی نوبت‌بندی شود.","done":false,"linkId":null}]},{"title":"جلسهٔ ۲ — الگوی حرکتی","plan":"نوشتن در هوا و ماسه؛ توالی حرکت پیش از فشار مداد.","criterion":"اجرای الگوی حرف هدف در ماسه بدون راهنما.","items":[{"type":"exercise","text":"نوشتن در هوا و ماسه: حرف را اول بزرگ در هوا و بعد در ماسه بنویسد.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000104"},{"type":"homework","text":"سه‌گانهٔ خط‌کشی نوشتن: خط‌کشی، فاصله و اندازهٔ حرف در برگهٔ خانه.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000204"}]},{"title":"جلسهٔ ۳ — کیفیت روی خط","plan":"سه سطرِ خوب به‌جای یک صفحه؛ مقایسهٔ برگهٔ امروز با نمونهٔ مبنا.","criterion":"سه سطر پیاپی روی خط با فاصلهٔ پایدار.","items":[{"type":"exercise","text":"سه سطرِ خوب: فقط سه سطر تمیز و روی خط؛ کیفیت، نه حجم.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000105"},{"type":"homework","text":"تمرین حرف‌های آینه‌ای (ب/ت/ث/ن/ی) — تمایز دیداری و جهت.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000203"}]},{"title":"جلسهٔ ۴ — دیکتهٔ هدفمند","plan":"اول بگو، بعد بنویس؛ دیکتهٔ کوتاه با کلمات هدف جلسه‌های قبل.","criterion":"کاهش خطای دیکته نسبت به مبنا در پروب.","items":[{"type":"exercise","text":"اول بگو، بعد بنویس: جمله را بلند بگوید، بعد بنویسد.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000106"},{"type":"probe","text":"پروب پیگیری — خطای دیکته و روانی (ce-probe-write-v1).","done":false,"linkId":null}]},{"title":"جلسهٔ ۵ — جمع‌بندی دوره","plan":"پروب پایانی، مقایسهٔ روند و تصمیم تداوم/کاردرمانی.","criterion":"معیار ۸۰٪ در دو جلسهٔ پیاپی یا تمدید دوره.","items":[{"type":"probe","text":"پروب پایانی — مقایسه با مبنا و معیار تسلط ۸۰٪ در دو جلسهٔ پیاپی.","done":false,"linkId":null},{"type":"instruction","text":"نمونهٔ تاریخ‌دار ماهانه نگه داشته شود؛ در خانه کیفیت سنجیده شود نه حجم.","done":false,"linkId":null}]}]',
  1,
  1,
  'seed-m128'
);

INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000005',
  'sys-sld-math',
  'اختلال یادگیری ریاضی — از ملموس به نماد',
  'قالب سیستمی نارساریاضی: پروب سلیقهٔ حساب به‌عنوان مبنا، ساخت حس عدد با مهره و خط عدد و انتقال به موقعیت واقعی؛ با معیار تسلط ۸۰٪ در دو جلسهٔ پیاپی. تمرین از ملموس شروع می‌شود، نه جدول ضرب؛ بدون هنجار عددی جدید.',
  'learning',
  'dyscalculia',
  '[{"key":"baseline","title":"پروب پایهٔ حساب","hint":"ce-probe-calc-v1 — سلیقه و مقایسهٔ مقدار؛ اضطراب ریاضی هم ثبت شود."},{"key":"concrete","title":"حس عدد با مهره","hint":"جمع و کمتر/بیشتر با مهرهٔ واقعی؛ از ملموس به نماد."},{"key":"numberline","title":"خط عدد و مقایسه","hint":"ترتیب و فاصلهٔ عددها با بدن و خط عدد زمینی."},{"key":"applied","title":"حساب در موقعیت واقعی","hint":"خرید و باقی‌پول و مسئلهٔ کلامی چهارگام؛ تعمیم به زندگی."},{"key":"monitor","title":"پروب پیگیری و جمع‌بندی","hint":"پروب هر دو جلسه؛ تسلط = ۸۰٪ معیار در دو جلسهٔ پیاپی."}]',
  '[{"title":"جلسهٔ ۱ — پروب پایه و هدف‌گذاری","plan":"اجرای پروب حساب و هدف SMART روی سلیقه/مقایسهٔ مقدار.","criterion":"ثبت مبنا در پروب مسیر.","items":[{"type":"probe","text":"اجرای ce-probe-calc-v1 — ثبت سلیقهٔ حساب و مقایسهٔ مقدار به‌عنوان مبنا.","done":false,"linkId":null},{"type":"event","text":"مرور نتیجهٔ ce-sld-calc-v1 و افتراق اضطراب ریاضی از حس عدد.","done":false,"linkId":null}]},{"title":"جلسهٔ ۲ — ملموس","plan":"جمع و مقایسه با مهرهٔ واقعی؛ دیدن و لمس پیش از نماد.","criterion":"۸ مقایسهٔ درست از ۱۰ با مهره.","items":[{"type":"exercise","text":"شمارش با مهره‌های واقعی: جمع و کمتر/بیشتر را ببیند و لمس کند.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000107"},{"type":"homework","text":"بازی مقایسهٔ مقدار با کارت‌های نقطه: دیدن یکجای مقدار کوچک.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000205"}]},{"title":"جلسهٔ ۳ — خط عدد","plan":"خط عدد زمینی: ترتیب و فاصله با بدن؛ سپس روی کاغذ.","criterion":"قرار دادن ۵ عدد در ترتیب درست روی خط.","items":[{"type":"exercise","text":"خط عدد روی زمین: پریدن روی خط عدد و فهم ترتیب و فاصله‌ها.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000109"},{"type":"probe","text":"پروب پیگیری — سلیقهٔ حساب نسبت به مبنا (ce-probe-calc-v1).","done":false,"linkId":null}]},{"title":"جلسهٔ ۴ — موقعیت واقعی","plan":"بازی فروشگاه و مسئلهٔ کلامی چهارگام؛ تعمیم حس عدد.","criterion":"حل یک مسئلهٔ کلامی با چیدمان درست گام‌ها.","items":[{"type":"exercise","text":"بازی فروشگاه: خرید و باقی‌پول با سکهٔ اسباب‌بازی.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000108"},{"type":"homework","text":"مسئلهٔ کلامی چهارگام خانه: بخوان، بشمار، عمل کن، وارسی کن.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000206"}]},{"title":"جلسهٔ ۵ — جمع‌بندی دوره","plan":"پروب پایانی و مقایسهٔ روند؛ برنامهٔ مرور خانگی با مهره و خط عدد.","criterion":"معیار ۸۰٪ در دو جلسهٔ پیاپی یا تمدید دوره.","items":[{"type":"probe","text":"پروب پایانی — مقایسه با مبنا و معیار تسلط ۸۰٪ در دو جلسهٔ پیاپی.","done":false,"linkId":null},{"type":"instruction","text":"در خانه از مهره و خط عدد شروع کنید، نه جدول ضرب؛ پیام خانواده.","done":false,"linkId":null}]}]',
  1,
  1,
  'seed-m128'
);

INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000006',
  'sys-anxiety-emotion',
  'اضطراب و تنظیم هیجانی — مواجههٔ پله‌ای',
  'قالب سیستمی اضطراب کودکان: SCARED والد برای خط پایه و بازسنجی، آموزش چرخهٔ اجتناب به خانواده، خودآرام‌سازی روزانه و پله‌های کوچک مواجهه از نزدیک صفر. حذف موقعیت به‌عنوان راه‌حل نقض اصل این مسیر است؛ تشخیص نیست و تفریقی لازم دارد.',
  'mental_ot',
  'anxiety',
  '[{"key":"assess","title":"SCARED والد و تفریقی","hint":"ce-scared-p-v1 — کل و پنج عامل؛ ناهم‌رأیی خانه/مدرسه بررسی شود."},{"key":"psycho","title":"آموزش چرخهٔ اجتناب","hint":"خانواده «همراهِ آرام» باشد، نه حذف‌کنندهٔ موقعیت."},{"key":"coping","title":"خودآرام‌سازی روزانه","hint":"تنفس بوی گل/فوت شمع؛ کوتاه و روزانه، نه فقط موقع بحران."},{"key":"exposure","title":"پله‌های مواجهه","hint":"ترسومتر ۰ تا ۱۰ و شروع از پلهٔ نزدیک صفر؛ نقش‌بازی پیش از موقعیت واقعی."},{"key":"monitor","title":"بازسنجی و تثبیت","hint":"بازپرسانی SCARED پس از ۴ تا ۶ هفته؛ جشن موفقیت‌های کوچک."}]',
  '[{"title":"جلسهٔ ۱ — خط پایه و آموزش خانواده","plan":"SCARED والد، انتخاب عامل پرنمره به‌عنوان محور برنامه؛ قرارداد همراهی خانواده.","criterion":"SCARED ثبت و یک موقعیت اجتناب‌شده برای ترسومتر انتخاب شود.","items":[{"type":"event","text":"ثبت SCARED والد (ce-scared-p-v1) — کل و پنج عامل به‌عنوان مبنا.","done":false,"linkId":null},{"type":"instruction","text":"جلسهٔ آموزش خانواده: همراهِ آرام بودن، نه حذف‌کنندهٔ موقعیت؛ چرخهٔ اجتناب توضیح داده شود.","done":false,"linkId":null}]},{"title":"جلسهٔ ۲ — خودآرام‌سازی روزانه","plan":"آموزش تنفس و تمرین روزانه در حالت آرام تا خودکار شود.","criterion":"اجرای روزانهٔ تنفس یک هفتهٔ کامل.","items":[{"type":"exercise","text":"تنفس «بوی گل، فوت شمع»: بو کشیدن آرام و فوت طولانی.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000119"},{"type":"homework","text":"روزی یک بار تنفس در حالت آرام؛ اول برای کودک آشنا، بعد در موقعیت خفیف.","done":false,"linkId":null}]},{"title":"جلسهٔ ۳ — ترسومتر","plan":"ساخت ترسومتر کودک و رتبه‌بندی موقعیت‌ها؛ انتخاب پلهٔ اول نزدیک صفر.","criterion":"ترسومتر کامل با حداقل سه موقعیت رتبه‌بندی‌شده.","items":[{"type":"exercise","text":"ترسومتر و پله‌ها: ترس روی ترسومتر ۰ تا ۱۰ و پله‌های کوچک مواجهه.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000120"},{"type":"homework","text":"ترسومتر خانه و قفسهٔ پله‌ها: ثبت مواجهه‌ها با مقیاس ۰ تا ۱۰.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000209"}]},{"title":"جلسهٔ ۴ — مواجههٔ تمرینی","plan":"نقش‌بازی موقعیت در امنیت جلسه، سپس پلهٔ واقعی کوچک؛ طرح مقابلهٔ اگر-آنگاه.","criterion":"انجام یک پلهٔ واقعی و ثبت نمرهٔ ترس پیش/بعد.","items":[{"type":"exercise","text":"نقش‌بازی موقعیت: موقعیت ترسناک در نقش‌بازی امن تمرین شود.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000121"},{"type":"homework","text":"یک پلهٔ مواجههٔ کوچک از نزدیک صفر؛ حذف موقعیت ممنوع.","done":false,"linkId":null}]},{"title":"جلسهٔ ۵ — جمع‌بندی و بازسنجی","plan":"بازپرسانی SCARED، مقایسه با مبنا و برنامهٔ تداوم مواجهه در خانه.","criterion":"بازسنجی ثبت و روند به خانواده گزارش شود.","items":[{"type":"event","text":"بازپرسانی SCARED پس از ۴ تا ۶ هفته و مقایسه با مبنا (ce-scared-p-v1).","done":false,"linkId":null},{"type":"instruction","text":"جشن کوچک موفقیت‌ها؛ تعریف از شجاعتِ پلهٔ کوچک، نه حذف ترس.","done":false,"linkId":null}]}]',
  1,
  1,
  'seed-m128'
);

INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000007',
  'sys-speech-delay',
  'تأخیر زبان-گفتار — محرک زبانی خانه‌محور',
  'قالب سیستمی تأخیر زبان: اول بستن گیت کم‌شنوایی، بعد چک‌لیست ملاکی زبان، سپس افزایش محرک و مدل‌دادن خانه‌محور با بازی واژه و دستورهای پلکانی. واژه‌اندوزی با تصویر و جمله بازی‌گونه پیش می‌رود؛ جایگزین گفتاردرمانی تخصصی نیست.',
  'mental_ot',
  'speech_language',
  '[{"key":"gate","title":"گیت کم‌شنوایی","hint":"پیش از هر مداخله ارجاع شنوایی‌سنجی؛ کم‌شنوایی اول افتراق می‌شود."},{"key":"assess","title":"چک‌لیست ملاکی زبان","hint":"ce-speech-criteria-v1 — فهم/بیان و الگوی تکراری/حسی برای افتراق اتیسم."},{"key":"input","title":"افزایش محرک و مدل‌دادن","hint":"گفت‌وگوی کوتاه روزانه؛ مدل‌دادن واژهٔ دقیق به‌جای اصلاح لفظی."},{"key":"practice","title":"بازی واژه و جمله","hint":"جعبهٔ واژه، توصیف-حدس و دنبالهٔ دستور پلکانی."},{"key":"monitor","title":"پیگیری و ارجاع","hint":"نوبت‌بندی گفتاردرمانگر؛ دفترچهٔ پیام مرکز-خانه برای یک‌زبانی شدن."}]',
  '[{"title":"جلسهٔ ۱ — گیت شنوایی","plan":"اطمینان از سلامت شنوایی پیش از مداخله زبانی؛ آموزش مدل‌دادن به خانواده.","criterion":"نتیجهٔ شنوایی‌سنجی ثبت یا نوبت آن پیگیری شود.","items":[{"type":"event","text":"ارجاع شنوایی‌سنجی — پیش از هر مداخلهٔ زبانی گیت کم‌شنوایی بسته شود.","done":false,"linkId":null},{"type":"instruction","text":"گفت‌وگوی کوتاه روزانه؛ مدل‌دادن واژهٔ دقیق، نه اصلاح لفظی.","done":false,"linkId":null}]},{"title":"جلسهٔ ۲ — ارزیابی ملاکی","plan":"چک‌لیست ملاکی زبان و نقشهٔ فهم/بیان؛ شروع جعبهٔ واژه.","criterion":"چک‌لیست ثبت و دو واژهٔ هدف هفته انتخاب شود.","items":[{"type":"event","text":"ثبت چک‌لیست ملاکی زبان/گفتار (ce-speech-criteria-v1).","done":false,"linkId":null},{"type":"exercise","text":"جعبهٔ واژه: هر روز چند واژهٔ دقیق با تصویر و جمله.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000116"}]},{"title":"جلسهٔ ۳ — جمله‌سازی بازی‌گونه","plan":"توصیف-حدس برای گسترش جمله؛ تمرین خانگی واژه‌ساز.","criterion":"ساخت جملهٔ سه‌جزئی با واژهٔ هدف.","items":[{"type":"exercise","text":"توضیح بده و حدس بزن: یکی توصیف کند، دیگری حدس بزند.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000117"},{"type":"homework","text":"پنج بازی واژه‌ساز خانه: واژه‌اندوزی با تصویر و جمله، روزی پنج دقیقه.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000210"}]},{"title":"جلسهٔ ۴ — فهم شنیداری","plan":"دنبالهٔ دستور از یک مرحله به دو مرحلهٔ بازی‌وار؛ تعمیم به دستور کلاس.","criterion":"اجرای دستور دومرحله‌ای بدون تکرار.","items":[{"type":"exercise","text":"دنبالهٔ دستور: دستور دو مرحله‌ای ساده بدهید و کم‌کم بلندتر کنید.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000118"},{"type":"homework","text":"دستور دومرحله‌ایِ بازی‌وار در خانه؛ فهم شنیداری در قالب بازی.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000211"}]},{"title":"جلسهٔ ۵ — جمع‌بندی و ارجاع","plan":"جمع‌بندی واژه‌اندوزی؛ تصمیم نوبت گفتاردرمانگر و پیام یک‌زبانهٔ مرکز-خانه.","criterion":"گزارش خانواده ثبت و مسیر تخصصی مشخص شود.","items":[{"type":"instruction","text":"نوبت‌بندی گفتاردرمانگر در صورت تداوم تأخیر؛ جمع‌بندی برای کمیسیون/گفتاردرمانگر.","done":false,"linkId":null},{"type":"family","text":"دفترچهٔ پیام مرکز-خانه: واژه‌های هدف هفته در دو خط رد و بدل شود.","done":false,"linkId":null}]}]',
  1,
  1,
  'seed-m128'
);
